var t=`1106-shan-noodles`;var n=`world-1106`;var s=`MM`;var a=`southeast-asia`;var o=4;var r=33;var l={en:`Shan Noodles`,ua:`Шанська локшина`};var d={en:`Shan Noodles is a dish from Myanmar prepared with garlic, tomato, ground pork, light soy sauce. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Шанська локшина, страва кухні країни М'янма, яку готують із таких продуктів: часник, помідор, свинячий фарш, світлий соєвий соус. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`garlic`,4,`clove`],[`tomato`,280,`g`],[`canola-oil`,35,`ml`],[`ground-pork`,460,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 13 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 13 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:13,i:[[`chicken-stock`,400,`ml`],[`light-soy-sauce`,45,`ml`],[`chili-oil`,20,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`rice-noodles`,460,`g`],[`water`,1e3,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`fermented-mustard-greens`,120,`g`],[`green-onion`,35,`g`],[`peanut`,55,`g`]]}];var m={slug:t,id:n,country:`MM`,region:a,servings:4,minutes:33,title:l,text:d,steps:g};export{s as country,m as default,n as id,r as minutes,a as region,o as servings,t as slug,g as steps,d as text,l as title};